339 |   /**
340 |    * 私有方法
341 |    */
342 |   private subscribe<T>(
343 |     event: string,
344 |     handler: EventHandler<T> | AsyncEventHandler<T>,
345 |     isAsync: boolean,
346 |     handlerId?: string
347 |   ): Subscription {
348 |     const id = handlerId || this.generateHandlerId();
349 |     const handlerMap = isAsync ? this.asyncHandlers : this.handlers;
350 | 
351 |     let handlers = handlerMap.get(event);
352 |     if (!handlers) {
353 |       handlers = new Map();
354 |       handlerMap.set(event, handlers);
355 |     }
356 | 
357 |     // 检查监听器数量限制
358 |     if (handlers.size >= this.options.maxListeners) {
359 |       throw new Error(
360 |         `Maximum listeners (${this.options.maxListeners}) exceeded for event: ${event}`
361 |       );
362 |     }
363 | 
364 |     handlers.set(id, handler as any);
365 | 
366 |     // 更新指标
367 |     const metrics = this.getOrCreateMetrics(event);
368 |     metrics.totalHandlers++;
369 | 
370 |     return {
371 |       unsubscribe: () => this.off(event, id),
372 |       event,
373 |       handlerId: id,
374 |     };
375 |   }
